class Node:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def printPaths(root, targetSum):
    def findPaths(node, currentSum, path):
        if not node:
            return

        currentSum += node.val
        path.append(node.val)

        if currentSum == targetSum:
            result.append(path[:])

        findPaths(node.left, currentSum, path)
        findPaths(node.right, currentSum, path)

        path.pop()

    result = []
    findPaths(root, 0, [])
    return result
